const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

const expectedToken = $env.PODCAST_WEBHOOK_TOKEN || '';
const suppliedToken = headers['x-podcast-token'] || headers['X-Podcast-Token'] || body.token || '';
if (expectedToken && suppliedToken !== expectedToken) {
  throw new Error('Unauthorized: invalid x-podcast-token');
}

const sourceUrl = String(body.source_url || '').trim();
const transcript = String(body.transcript || '').trim();

if (!sourceUrl) {
  throw new Error('source_url is required');
}
if (transcript.length < 50) {
  throw new Error('transcript is required and must contain at least 50 characters');
}

return [{
  json: {
    source_url: sourceUrl,
    transcript: transcript.slice(0, 180000),
    episode_title: String(body.episode_title || '').trim(),
    episode_number: String(body.episode_number || '').trim(),
    guest: String(body.guest || '').trim(),
    audience: String(body.audience || 'technical leaders, builders, and practitioners interested in AI').trim(),
    language: String(body.language || 'English').trim(),
    cta: String(body.cta || '').trim(),
    brand_notes: String(body.brand_notes || '').trim(),
    requested_by: String(body.requested_by || '').trim(),
    generated_at: new Date().toISOString()
  }
}];

