const meta = $('Normalize request').first().json;
const response = $json;

function getText(resp) {
  if (!resp) return '';
  // OpenAI-compatible shape (served by claude-bridge, not Anthropic's own API).
  return resp.choices?.[0]?.message?.content || '';
}

const text = getText(response);
if (!text) {
  return [{
    json: {
      success: false,
      source_url: meta.source_url,
      generated_at: meta.generated_at,
      error: response?.error?.message || 'Claude returned no text',
      model: response?.model || 'claude-sonnet-5'
    }
  }];
}

try {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) throw new Error('No JSON object found in Claude response');
  const pack = JSON.parse(text.slice(start, end + 1));
  return [{
    json: {
      success: true,
      source_url: meta.source_url,
      generated_at: meta.generated_at,
      model: response?.model || 'claude-sonnet-5',
      usage: response?.usage || null,
      pack
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      source_url: meta.source_url,
      generated_at: meta.generated_at,
      error: String(e?.message || e),
      raw_response_preview: text.slice(0, 2000),
      model: response?.model || 'claude-sonnet-5'
    }
  }];
}
